1	import { Buffer, isUtf8 } from 'node:buffer';
2	import { readFileSync, statSync } from 'node:fs';
3	import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
4	import { createRequire } from 'node:module';
5	import {
6		charIn,
7		createRegExp,
8		exactly,
9		global,
10		maybe,
11		oneOrMore,
12		whitespace,
13		wordChar,
14	} from 'magic-regexp';
15	import * as path from 'pathe';
16	import { analyze, type NodeOfType, type Reference } from 'yuku-analyzer';
17	
18	/**
19	 * Reusable create-react-app compatibility capabilities for a Vite build.
20	 *
21	 * Every export here is application agnostic: the shapes handled are the ones
22	 * create-react-app itself defines (HTML template placeholders, `process.env`
23	 * inlining, the ambient `global` identifier, webpack's automatic Node core
24	 * module polyfills, webpack's sloppy-mode CommonJS module wrapper, webpack
25	 * tilde specifiers, and the copied public directory). No capability branches on
26	 * an application name, revision, or source string.
27	 */
