432	const dependencyDirectorySegment = 'node_modules';
433	
434	/**
435	 * The extensions webpack 4 fed through its sloppy CommonJS wrapper. `.mjs` is
436	 * absent on purpose: webpack forced those to harmony, hence to strict mode.
437	 */
438	const sloppyCommonJsExtensions: ReadonlySet<string> = new Set(['.js', '.cjs', '']);
