445	export type CraSloppyModuleKind = 'sloppy-commonjs' | 'ecmascript-module' | 'unanalyzable';
446	
447	export type CraImplicitGlobalScan = Readonly<{
448		kind: CraSloppyModuleKind;
449		names: readonly string[];
450		diagnostics: readonly string[];
451	}>;
