453	/**
454	 * Classify a module the way webpack 4 did and, when it is one of the sloppy
455	 * CommonJS modules, report the names it assigns without ever declaring them.
456	 *
457	 * The scan rides a real scope resolution: a name counts only when a write
458	 * reference resolves to no binding in any enclosing scope, so a local variable,
459	 * a parameter, a `catch` binding or a hoisted `var` of the same name elsewhere
460	 * in the module never produces a false report, and a shadowed inner name never
461	 * hides a genuine implicit global.
462	 */
463	export function scanCraImplicitGlobals(code: string, id = 'dependency.js'): CraImplicitGlobalScan {
464		const script = analyze(code, { path: id, lang: 'js', sourceType: 'script' });
465		const scriptErrors = script.diagnostics.filter((entry) => entry.severity === 'error');
466		if (scriptErrors.length > 0) {
467			// Harmony syntax is the ordinary reason a script parse fails, and webpack
468			// ran those modules in strict mode as well. Anything that parses as
469			// neither is a module this capability cannot reason about.
470			const esm = analyze(code, { path: id, lang: 'js', sourceType: 'module' });
471			const esmErrors = esm.diagnostics.filter((entry) => entry.severity === 'error');
472			return esmErrors.length === 0
473				? Object.freeze({ kind: 'ecmascript-module', names: [], diagnostics: [] })
474				: Object.freeze({
475						kind: 'unanalyzable',
476						names: [],
477						diagnostics: esmErrors.map((entry) => entry.message),
478					});
479		}
480		if (script.imports.length > 0 || script.exports.length > 0)
481			return Object.freeze({ kind: 'ecmascript-module', names: [], diagnostics: [] });
482		const names = new Set<string>();
483		for (const reference of script.unresolvedReferences)
484			if (reference.isWrite) names.add(reference.name);
485		return Object.freeze({
486			kind: 'sloppy-commonjs',
487			names: [...names].sort(compareUtf16CodeUnits),
488			diagnostics: [],
489		});
490	}
