492	/**
493	 * The prelude that gives a sloppy-mode implicit global its binding. Creating
494	 * the property is conditional, so a name the host genuinely owns — or one an
495	 * earlier dependency already assigned — keeps the value it has; only the
496	 * binding webpack's global object would have carried is added.
497	 */
498	export function craImplicitGlobalPrelude(names: readonly string[]): string {
499		if (names.length === 0) return '';
500		const statements = names
501			.map((name) => {
502				const key = JSON.stringify(name);
503				return `if (!(${key} in globalThis)) globalThis[${key}] = void 0;`;
504			})
505			.join(' ');
506		return `/* webpack sloppy-mode implicit globals */ ${statements}`;
507	}
