512	 * line number in the original module, and therefore every source map that
513	 * refers to it, still points where it did. A hashbang keeps the first line.
514	 */
515	export function craSloppyCommonJsSource(code: string, names: readonly string[]): string {
516		const prelude = craImplicitGlobalPrelude(names);
517		if (prelude === '') return code;
518		if (!code.startsWith('#!')) return `${prelude}${code}`;
519		const firstLineEnd = code.indexOf('\n');
520		if (firstLineEnd === -1) return `${code}\n${prelude}`;
521		return `${code.slice(0, firstLineEnd + 1)}${prelude}${code.slice(firstLineEnd + 1)}`;
