539			name: 'versionless-cra-sloppy-commonjs-globals',
540			enforce: 'pre',
541			transform(code, id) {
542				const file = pathWithoutQuery(id);
543				if (!craIsDependencyModule(file)) return null;
544				if (!sloppyCommonJsExtensions.has(path.extname(file))) return null;
