548						`create-react-app compatibility: the dependency module ${file} parses as neither ` +
549							`a script nor an ECMAScript module, so webpack 4's sloppy-mode CommonJS wrapper ` +
550							`cannot be reproduced for it and an implicit global it may rely on would reach ` +
551							`the browser as a ReferenceError. Parser diagnostics: ${scan.diagnostics.join('; ')}`,
552					);
553				if (scan.names.length === 0) return null;
554				options.observe?.({ id: file, names: scan.names });
