660	export function craInvalidUtf8ByteOffsets(bytes: Uint8Array): readonly number[] {
661		const offsets: number[] = [];
662		let index = 0;
663		while (index < bytes.length) {
664			const lead = bytes[index] as number;
665			const length = utf8SequenceLength(lead);
666			if (length === 0) {
667				offsets.push(index);
668				index += 1;
669				continue;
670			}
671			if (length === 1) {
672				index += 1;
673				continue;
674			}
675			const lowestSecond = lead === 0xe0 ? 0xa0 : lead === 0xf0 ? 0x90 : 0x80;
