1116	export type CraModuleExportSurfaceResolver = (specifier: string) => CraModuleExportSurface | null;
1117	
1118	export type CraDanglingImportNeutralization = Readonly<{
1119		code: string;
1120		neutralized: readonly Readonly<{ specifier: string; name: string }>[];
1121	}>;
1122	
1123	/**
1124	 * Neutralize the dangling named imports of a dependency ES module: the pure
1125	 * core of the capability, given `resolve` to read each relative target's export
1126	 * surface. Returns `null` when the module does not analyse as an ES module, has
1127	 * no imports, or carries no dangling-and-safe import — in every one of those
1128	 * cases the source is left exactly as it was.
1129	 */
1130	export function craNeutralizeDanglingImports(
1131		code: string,
1132		id: string,
1133		resolve: CraModuleExportSurfaceResolver,
1134	): CraDanglingImportNeutralization | null {
1135		const module = analyze(code, { path: id, lang: 'js', sourceType: 'module' });
1136		if (module.diagnostics.some((entry) => entry.severity === 'error')) return null;
1137		if (module.imports.length === 0) return null;
1138	
1139		const surfaces = new Map<string, CraModuleExportSurface | null>();
1140		const declarations = new Map<CraImportDeclarationNode, CraImportDeclarationSpecifier[]>();
1141		const neutralized: { specifier: string; name: string }[] = [];
1142	
1143		for (const record of module.imports) {
1144			if (record.isNamespace || record.isSideEffect || record.typeOnly) continue;
1145			if (record.name === null || record.name === 'default') continue;
1146			if (record.local === null) continue;
1147			if (!record.specifier.startsWith('.')) continue;
1148			if (!surfaces.has(record.specifier)) surfaces.set(record.specifier, resolve(record.specifier));
1149			const surface = surfaces.get(record.specifier) ?? null;
1150			if (surface === null || surface.hasStar) continue;
1151			if (surface.names.has(record.name)) continue;
1152			if (!record.local.references.every(craReferenceSafeUnderUndefined)) continue;
1153			const declaration = module.parentOf(record.node);
1154			if (declaration === null || declaration.type !== 'ImportDeclaration') continue;
1155			const specifier = declaration.specifiers.find((entry) => entry === record.node);
1156			if (specifier === undefined) continue;
1157			const group = declarations.get(declaration) ?? [];
1158			group.push(specifier);
1159			declarations.set(declaration, group);
1160			neutralized.push({ specifier: record.specifier, name: record.name });
1161		}
1162	
1163		if (declarations.size === 0) return null;
1164	
1165		const edits: { start: number; end: number; text: string }[] = [];
1166		for (const [declaration, neutralizedSpecifiers] of declarations) {
1167			const dropped = new Set<CraImportDeclarationSpecifier>(neutralizedSpecifiers);
1168			const kept = declaration.specifiers.filter((specifier) => !dropped.has(specifier));
1169			const source = code.slice(declaration.source.start, declaration.source.end);
1170			const importText =
1171				kept.length > 0 ? `import ${craImportClause(kept)} from ${source};` : `import ${source};`;
1172			const bindings = neutralizedSpecifiers
1173				.map((specifier) => `const ${specifier.local.name} = ${craDanglingBindingValue};`)
1174				.join(' ');
1175			edits.push({ start: declaration.start, end: declaration.end, text: `${importText} ${bindings}` });
1176		}
1177	
1178		edits.sort((left, right) => right.start - left.start);
1179		let output = code;
1180		for (const edit of edits) output = `${output.slice(0, edit.start)}${edit.text}${output.slice(edit.end)}`;
1181		return Object.freeze({ code: output, neutralized });
1182	}
1183	
1184	export type CraMissingExportToleranceOptions = Readonly<{
1185		observe?: (record: CraDanglingImportRecord) => void;
1186	}>;
1187	
1188	/**
1189	 * Reproduce webpack 4's `undefined` resolution of a dangling named import for a
1190	 * self-inconsistent dependency ES module. The plugin scopes itself to
1191	 * dependency modules, reads each dangling import's target export surface from
1192	 * disk (cached, so a shared target is analysed once), and rewrites only the
1193	 * imports it can prove are both genuinely absent and safe under `undefined`. A
1194	 * module that links cleanly is returned untouched.
1195	 */
1196	export function createCraMissingExportTolerancePlugin(
1197		options: CraMissingExportToleranceOptions = {},
1198	): CraTransformPlugin {
1199		const cache = new Map<string, CraModuleExportSurface | null>();
1200		const surfaceOf = (file: string): CraModuleExportSurface | null => {
1201			const cached = cache.get(file);
1202			if (cached !== undefined || cache.has(file)) return cached ?? null;
1203			const surface = craReadModuleExportSurface(file);
1204			cache.set(file, surface);
1205			return surface;
1206		};
1207		return {
1208			name: 'versionless-cra-missing-export-tolerance',
1209			enforce: 'pre',
1210			transform(code, id) {
1211				if (id.startsWith('\0')) return null;
1212				const file = pathWithoutQuery(id);
1213				if (!craIsDependencyModule(file)) return null;
1214				if (!decodableModuleExtensions.has(path.extname(file))) return null;
1215				if (!code.includes('import')) return null;
1216				const result = craNeutralizeDanglingImports(code, file, (specifier) => {
1217					const target = craResolveRelativeModule(file, specifier);
1218					return target === null ? null : surfaceOf(target);
1219				});
1220				if (result === null) return null;
1221				for (const record of result.neutralized)
1222					options.observe?.({ id: file, specifier: record.specifier, name: record.name });
1223				return { code: result.code, map: null };
1224			},
1225		};
1226	}
1227	
1228	export type CraViteAdapterOptions = Readonly<{
1229		publicDirectory: string;
1230		templateFile?: string;
1231		applicationRoot?: string;
1232		observeImplicitGlobals?: (record: CraImplicitGlobalRecord) => void;
1233		observeDecodedModules?: (record: CraDecodedModuleRecord) => void;
1234		observeDanglingImports?: (record: CraDanglingImportRecord) => void;
1235	}>;
1236	
1237	export type CraViteAdapterPlugins = readonly [
1238		CraLoadPlugin,
1239		CraModuleTypePlugin,
1240		CraTransformPlugin,
1241		CraTransformPlugin,
1242		CraTransformPlugin,
1243		CraNodeCoreModulePlugin,
1244		CraDefinePlugin,
1245		CraOutputPlugin,
1246	];
1247	
1248	/**
1249	 * The create-react-app compatibility plugin set: webpack's lenient module-source
1250	 * decoding, JSX in application-source JavaScript, tilde CSS specifier
1251	 * rewriting, webpack's sloppy-mode CommonJS wrapper for dependency modules,
1252	 * webpack's `undefined` resolution of a dangling named import in a
1253	 * self-inconsistent dependency ES module, webpack's automatic Node core module
1254	 * polyfills, the ambient `global` identifier, plus public directory
1255	 * replication.
1256	 *
1257	 * Decoding leads, because it is the only capability here that acts on bytes: a
1258	 * module has to become text before any transform above can read it. The JSX
1259	 * module type follows immediately, because a module has to be parseable before
1260	 * any later transform's output is meaningful.
1261	 */
1262	export function createCraViteAdapter(options: CraViteAdapterOptions): CraViteAdapterPlugins {
1263		return [
1264			createCraNonUtf8ModuleSourcePlugin(
1265				options.observeDecodedModules === undefined
1266					? {}
1267					: { observe: options.observeDecodedModules },
1268			),
1269			createCraJavaScriptJsxPlugin(),
1270			createCraTildeCssImportPlugin(),
1271			createCraSloppyCommonJsGlobalsPlugin(
1272				options.observeImplicitGlobals === undefined
1273					? {}
1274					: { observe: options.observeImplicitGlobals },
1275			),
1276			createCraMissingExportTolerancePlugin(
1277				options.observeDanglingImports === undefined
1278					? {}
1279					: { observe: options.observeDanglingImports },
1280			),
1281			createCraNodeCoreModulePlugin(
1282				options.applicationRoot === undefined
1283					? {}
1284					: { applicationRoot: options.applicationRoot },
1285			),
1286			createCraGlobalIdentifierPlugin(),
1287			createCraPublicDirectoryPlugin({
1288				directory: options.publicDirectory,
1289				exclude: [options.templateFile ?? 'index.html'],
1290			}),
1291		];
1292	}
