6		WITNESS_REACT_CYPRESS_RWA_PLACEHOLDERS,
7	} from '../../../core/src/receipts/witness-react-cypress-rwa.ts';
8	import { buildLoopbackBackendInventory } from './live-backend.ts';
9	import type { AppSpec } from './real-app-run.ts';
