11	/** A decodable placeholder the harness answers in-context for the app's S3 avatar SVGs. */
12	const CYPRESS_RWA_PLACEHOLDER_SVG =
13		'<svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 64 64"><rect width="64" height="64" fill="#dddddd"/></svg>';
14	
15	/**
16	 * The cypress-realworld-app live-backend Witness spec — the corpus's first
17	 * stateful vertical.
18	 *
19	 * The journey is wired straight from the application's own Cypress specs under
20	 * `cypress/tests/ui`, which are the intended exercisable surface: `auth.spec`
21	 * (sign up / sign in), `new-transaction.spec` (send money), `transaction-feeds`
22	 * (public / contacts / personal filters), `notifications` and `user-settings`.
23	 * Every gesture is addressed by the application's own `data-test` attribute, so
24	 * the selectors are the app's, not the harness's. The backend declaration spawns
25	 * the application's REAL Express-over-lowdb server on a second bounded loopback
26	 * origin and re-seeds it from its frozen snapshot before each pass.
27	 *
28	 * Redaction is structural: the journey signs up a fresh, NON-SEED corpus actor
29	 * and acts as it; the one place a seed identity is touched — the recipient of
30	 * the payment — is captured from search and never written literally, it is
31	 * declared as `{recipient-handle}` and normalized away. No seed username,
32	 * password or hash is hard-coded here, and the redaction test enforces it.
33	 *
34	 * This spec is exported for the runner unit to execute; no evidence is published
35	 * from the unit that authored it.
36	 */
37	export function reactCypressRwaWitnessSpec(): AppSpec {
38		const actor = WITNESS_REACT_CYPRESS_RWA_ACTOR;
39		return {
40			app: 'cypress-realworld-app',
41			framework: 'react',
42			canonicalReceipt: 'evidence/runs/react-cypress-rwa/rerun-2026-08-12/build-profile.json',
43			canonicalDigest: '981fbff5b2c8a4e257544bf6ba6abb25334c686fd56605edd6e0a89f4795d1ae',
44			canonicalBinding: 'file-sha256',
45			sources: {
46				baseline: '.versionless/stage/witness-real-app/lanes/cypress-realworld-app/baseline',
47				migrated: '.versionless/stage/witness-real-app/lanes/cypress-realworld-app/migrated',
48			},
49			// A real load to `/signup`: the signin page's signup link does not
50			// SPA-navigate under automation (measured), so the journey starts at the
51			// signup route directly and the SPA index fallback renders the SignUpForm.
52			initialRoute: '/signup',
53			/**
54			 * The application's own server. Command and port are the app's declared
55			 * ones; the harness copies the frozen seed over the mutable lowdb store and
56			 * runs the app's own prerequisite mock-config copy before boot, then waits
57			 * for the auth-gated `/checkAuth` route to answer — a 401 before any session
58			 * exists is a server that is up.
59			 */
60			backend: {
61				command: 'yarn',
62				args: ['start:api'],
63				cwd: '.',
64				port: 3001,
65				// The built SPA calls its backend absolutely at `http://localhost:3001`
66				// and the server's own CORS allow-origin is `http://localhost:<port>`, so
67				// the document has to be served under `localhost` too or every
68				// credentialed request is cross-origin. Both are the application's own
69				// facts, declared here rather than branched on in the runner.
70				host: 'localhost',
71				// The server reads `REACT_APP_PORT` to build that CORS allow-origin; the
72				// harness injects the actual served SPA port into it so the allow-list
73				// resolves to the exact origin the browser is served from.
74				corsOriginPortEnv: ['REACT_APP_PORT'],
75				seed: { snapshot: 'data/database-seed.json', store: 'data/database.json' },
76				prepare: [{ from: 'scripts/mock-aws-exports.js', to: 'src/aws-exports.js' }],
77				health: { path: '/checkAuth', okStatus: [401] },
78				readyTimeoutMs: 30_000,
79			},
80			placeholders: WITNESS_REACT_CYPRESS_RWA_PLACEHOLDERS,
81			// The application renders every user's avatar from an `<img src>` at its own
82			// S3 SVG bucket; declaring the full seed-avatar set is what makes an
83			// undeclared seam fail the run. The harness answers every one in-context, so
84			// none leaves the machine.
85			mockedNonLoopbackSeams: {
86				baseline: WITNESS_REACT_CYPRESS_RWA_MOCKED_SEAMS,
87				migrated: WITNESS_REACT_CYPRESS_RWA_MOCKED_SEAMS,
88			},
89			// Non-loopback requests are answered in-context: the avatar SVGs get a
90			// decodable placeholder image so the page renders clean; anything else an
91			// empty 204. The host counts these as mockedNonLoopback and keeps
92			// successfulNonLoopback at zero.
93			transport: async (request) => {
94				if (request.pathname.endsWith('.svg'))
95					return {
96						action: 'fulfill',
97						status: 200,
98						contentType: 'image/svg+xml',
99						body: Buffer.from(CYPRESS_RWA_PLACEHOLDER_SVG),
100					};
101				return { action: 'fulfill', status: 204, contentType: 'text/plain', body: Buffer.alloc(0) };
102			},
103			journey: async (context, page, _transportEvidence, lifecycle) => {
104				await page.trackEvents('click', 'input', 'change', 'keydown', 'mouseover');
105				const expectPage = context.expect.page;
106				// The MUI `data-test` on signup/signin/bankaccount/transaction-create is on
107				// the TextField ROOT, so the real <input> is `[data-test=…] input`; the
108				// settings and peer-search fields carry `data-test` on the <input> itself,
109				// so they are addressed without ` input`. Both are measured off the live DOM.
110	
111				// Auth — the initial load is a real navigation to `/signup`; sign a fresh
112				// non-seed actor up, then sign in as it. No seed identity is touched.
113				await expectPage.exists(page, '[data-test=signup-first-name] input');
114				await page.type('[data-test=signup-first-name] input', actor.firstName);
115				await page.type('[data-test=signup-last-name] input', actor.lastName);
116				await page.type('[data-test=signup-username] input', actor.username);
117				await page.type('[data-test=signup-password] input', actor.password);
118				await page.type('[data-test=signup-confirmPassword] input', actor.password);
119				await page.click('[data-test=signup-submit]');
120				await expectPage.exists(page, '[data-test=signin-username] input');
121				await page.type('[data-test=signin-username] input', actor.username);
122				await page.type('[data-test=signin-password] input', actor.password);
123				await page.click('[data-test=signin-submit]');
124	
125				// Onboarding — the app's first-bank-account dialog (a POST /graphql
126				// mutation), then the actor completes its required settings so a mutating
127				// PATCH /users/{created-user-id} is proven before any transfer. A fresh
128				// actor has no email or phone, so Save stays disabled until both are set.
129				await expectPage.exists(page, '[data-test=user-onboarding-next]');
130				await page.click('[data-test=user-onboarding-next]');
131				await expectPage.exists(page, '[data-test=bankaccount-bankName-input] input');
132				await page.type('[data-test=bankaccount-bankName-input] input', 'Versionless Bank');
133				await page.type('[data-test=bankaccount-routingNumber-input] input', '987654321');
134				await page.type('[data-test=bankaccount-accountNumber-input] input', '123456789');
135				await page.click('[data-test=bankaccount-submit]');
136				await expectPage.exists(page, '[data-test=user-onboarding-next]');
137				await page.click('[data-test=user-onboarding-next]');
138				await expectPage.exists(page, '[data-test=sidenav-user-settings]');
139				await page.click('[data-test=sidenav-user-settings]');
140				await expectPage.exists(page, '[data-test=user-settings-email-input]');
141				await page.type('[data-test=user-settings-email-input]', 'prover@versionless.test');
142				await page.type('[data-test=user-settings-phoneNumber-input]', '6155551234');
143				await page.click('[data-test=user-settings-submit]');
144	
145				// Money movement — the substantive stateful step. Search a peer, pick the
146				// first result (its handle is captured and normalized, never recorded),
147				// and send a payment the backend mints an id for (POST /transactions).
148				await expectPage.exists(page, '[data-test=nav-top-new-transaction]');
149				await page.click('[data-test=nav-top-new-transaction]');
150				await expectPage.exists(page, '[data-test=user-list-search-input]');
151				await page.type('[data-test=user-list-search-input]', 'a');
152				await expectPage.exists(page, '[data-test^=user-list-item-]');
153				await page.click('[data-test^=user-list-item-]');
154				await expectPage.exists(page, '[data-test=transaction-create-amount-input] input');
155				await page.type('[data-test=transaction-create-amount-input] input', '15');
156				await page.type(
157					'[data-test=transaction-create-description-input] input',
158					'versionless-proof-payment',
159				);
160				await page.click('[data-test=transaction-create-submit-payment]');
161	
162				// The minted transaction round-trips lowdb into the actor's personal feed,
163				// and the balance settles — the substantive stateful assertion.
164				await expectPage.exists(page, '[data-test=sidenav-home]');
165				await page.click('[data-test=sidenav-home]');
166				await page.click('[data-test=nav-personal-tab]');
167				await expectPage.exists(page, '[data-test=transaction-list]');
168				await expectPage.bodyText(page, { contains: 'versionless-proof-payment' });
169				await expectPage.visible(page, '[data-test=sidenav-user-balance]');
170	
171				// Feed / filter — the three feeds the app ships. Contacts is empty for a
172				// fresh actor, so its settled shape is the app's own empty-list marker.
173				await page.click('[data-test=nav-public-tab]');
174				await expectPage.exists(page, '[data-test=transaction-list]');
175				await page.click('[data-test=nav-contacts-tab]');
176				await expectPage.exists(
177					page,
178					'[data-test=transaction-list], [data-test=empty-list-header]',
179				);
180				await page.click('[data-test=nav-personal-tab]');
181				await expectPage.exists(page, '[data-test=transaction-list]');
182	
183				// Notifications — read the app's own notification feed (GET /notifications).
184				await page.click('[data-test=sidenav-notifications]');
185				await expectPage.exists(
186					page,
187					'[data-test=notifications-list], [data-test=empty-list-header]',
188				);
189	
190				await expectPage.outcome(page, {
191					events: {
192						click: { atLeast: 10 },
193						input: { atLeast: 8 },
194						keydown: { atLeast: 8 },
195					},
196				});
197	
198				// The loopback-backend inventory, built generically from the run's own
199				// request ledger against the two bounded loopback origins.
200				const loopbackBackend =
201					lifecycle.requestOutcomes === undefined ||
202					lifecycle.backendOrigin === undefined ||
203					lifecycle.staticOrigin === undefined
204						? undefined
205						: buildLoopbackBackendInventory(
206								lifecycle.requestOutcomes(),
207								lifecycle.staticOrigin,
208								lifecycle.backendOrigin,
209								WITNESS_REACT_CYPRESS_RWA_BACKEND_CATEGORY,
210							);
211	
212				return {
213					assertions: [
214						'sign up and sign in as a fresh non-seed actor',
215						'onboarding first bank account and settings write',
216						'money movement to a placeholdered peer',
217						'minted transaction appears in the actor personal feed',
218						'public / contacts / personal feeds',
219						'notifications feed',
220						'clean page',
221					],
222					offlineEvidence: { state: 'not-applicable' },
223					...(loopbackBackend === undefined
224						? {}
225						: {
226								applicationJourney: {
227									state: 'live-loopback-backend-journey',
228									source: REACT_CYPRESS_RWA_SOURCE.revision,
229									loopbackBackend,
230								},
231							}),
232				};
233			},
234		};
235	}
