1	/**
2	 * Direct-Playwright diagnostic for the cypress-realworld-app live-backend journey.
3	 *
4	 * Unlike the witness-host calibration driver, this drives a raw Playwright page so
5	 * it can read the live DOM (`page.evaluate`), the current URL and the real network
6	 * ledger at each leg. It publishes nothing and asserts nothing; its only output is
7	 * a JSON dump on stdout used to calibrate the journey/schema pins to measured
8	 * reality. It boots the application's own Express-over-lowdb backend in its era
9	 * runtime cell, reseeded from the frozen snapshot, exactly as the serving path does.
10	 */
11	
12	import { type ChildProcess, spawn } from 'node:child_process';
13	import { copyFile } from 'node:fs/promises';
14	import { get } from 'node:http';
15	import { basename, join, resolve } from 'pathe';
16	import { chromium } from 'playwright';
17	import { canonicalize } from '../../../core/src/receipts/canonicalize.ts';
18	import { WITNESS_REACT_CYPRESS_RWA_ACTOR } from '../../../core/src/receipts/witness-react-cypress-rwa.ts';
19	import { startStaticServer } from '../witness/real-app-run.ts';
20	
21	const root = resolve(import.meta.dirname, '../../../..');
22	const workRoot = join(root, '.versionless/work/react-cypress-rwa');
23	const eraNodeBin = join(
24		root,
25		'.versionless/cache/react-cypress-rwa-runtime/node-v14.16.1-darwin-x64/bin',
26	);
27	const eraYarnBin = join(root, '.versionless/cache/react-cypress-rwa-baseline/npm-global/bin');
28	const chromiumExecutable = join(
29		root,
30		'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
31	);
32	
33	const laneStaticRoot: Record<string, string> = {
34		baseline: join(workRoot, 'baseline/build-run1'),
35		migrated: join(workRoot, 'target/build-vite'),
36	};
37	const backendLaneRoot = join(workRoot, 'baseline');
38	const BACKEND_PORT = 3001;
39	
40	async function probeHealth(url: string): Promise<number | null> {
41		return await new Promise<number | null>((settle) => {
42			const request = get(url, (response) => {
43				settle(response.statusCode ?? null);
44				response.resume();
45			});
46			request.setTimeout(500, () => request.destroy());
47			request.on('error', () => settle(null));
48		});
49	}
50	
51	const delay = (ms: number): Promise<void> =>
52		new Promise<void>((settle) => void setTimeout(settle, ms));
53	
54	async function bootBackend(frontendPort: number): Promise<{ close(): Promise<void> }> {
55		await copyFile(
56			join(backendLaneRoot, 'data/database-seed.json'),
57			join(backendLaneRoot, 'data/database.json'),
58		);
59		const child: ChildProcess = spawn('yarn', ['start:api'], {
60			cwd: backendLaneRoot,
61			env: {
62				...process.env,
63				PATH: `${eraNodeBin}:${eraYarnBin}:${process.env.PATH ?? ''}`,
64				PORT: String(BACKEND_PORT),
65				// The CORS allow-origin the backend builds is `http://localhost:${REACT_APP_PORT}`,
66				// so it must equal the static origin the browser is actually served from.
67				REACT_APP_PORT: String(frontendPort),
68				SKIP_YARN_COREPACK_CHECK: '1',
69			},
70			stdio: 'ignore',
71		});
72		const deadline = Date.now() + 45_000;
73		while (Date.now() < deadline) {
74			if ((await probeHealth(`http://127.0.0.1:${BACKEND_PORT}/checkAuth`)) === 401) break;
75			await delay(250);
76		}
77		return {
78			close: async () =>
79				await new Promise<void>((settle) => {
80					child.once('exit', () => settle());
81					child.kill('SIGTERM');
82					setTimeout(() => {
83						if (child.exitCode === null && child.signalCode === null) child.kill('SIGKILL');
84					}, 2_000);
85				}),
86		};
87	}
88	
89	export async function probeCypressRwaLane(lane: string): Promise<void> {
90		const actor = WITNESS_REACT_CYPRESS_RWA_ACTOR;
91		const staticRoot = laneStaticRoot[lane]!;
92		const staticServer = await startStaticServer(staticRoot, { profile: 'current-witness' });
93		// The static server binds 127.0.0.1; addressing it through `localhost` yields a
94		// `http://localhost:<port>` document origin that the backend CORS allow-list can match.
95		const staticPort = Number(new URL(staticServer.origin).port);
96		const appOrigin = `http://localhost:${staticPort}`;
97		const backend = await bootBackend(staticPort);
98		const browser = await chromium.launch({ executablePath: chromiumExecutable, headless: true });
99		const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
100		const page = await context.newPage();
101		const network: Array<{ method: string; url: string; status: number | null }> = [];
102		const backendOrigin = `http://localhost:${BACKEND_PORT}`;
103		const normalize = (raw: string): string => {
104			if (raw.startsWith(backendOrigin)) return `{backend}${raw.slice(backendOrigin.length)}`;
105			return raw;
106		};
107		page.on('response', (response) => {
108			const url = response.url();
109			if (url.startsWith(appOrigin)) return;
110			network.push({
111				method: response.request().method(),
112				url: normalize(url),
113				status: response.status(),
114			});
115		});
116		page.on('requestfailed', (request) => {
117			const url = request.url();
118			if (url.startsWith(appOrigin)) return;
119			network.push({
120				method: request.method(),
121				url: normalize(url),
122				status: null,
123			});
124		});
125		const consoleErrors: string[] = [];
126		page.on('console', (message) => {
127			if (message.type() === 'error') consoleErrors.push(message.text().slice(0, 200));
128		});
129		page.on('pageerror', (error) => consoleErrors.push(`PAGEERROR ${error.message.slice(0, 200)}`));
130	
131		const dataTests = async (): Promise<string[]> =>
132			await page.evaluate(() =>
133				[...document.querySelectorAll('[data-test]')]
134					.map((element) => (element as HTMLElement).dataset.test ?? '')
135					.filter((value, index, all) => all.indexOf(value) === index)
136					.sort(),
137			);
138	
139		const legs: Array<Record<string, unknown>> = [];
140		let netCursor = 0;
141		const snapshot = async (label: string): Promise<void> => {
142			legs.push({ label, url: new URL(page.url()).pathname, dataTests: await dataTests() });
143		};
144	
145		const clickIfPresent = async (selector: string, label: string): Promise<void> => {
146			try {
147				await page.locator(selector).first().click({ timeout: 4_000 });
148				legs.push({ action: label, selector, outcome: 'clicked' });
149			} catch (error: unknown) {
150				legs.push({
151					action: label,
152					selector,
153					outcome: `FAIL: ${(error instanceof Error ? error.message : String(error)).split('\n')[0]}`,
154				});
155			}
156			await delay(1_000);
157		};
158		const typeIfPresent = async (selector: string, value: string, label: string): Promise<void> => {
159			try {
160				await page.locator(selector).first().fill(value, { timeout: 4_000 });
161				legs.push({ action: label, selector, outcome: 'filled' });
162			} catch (error: unknown) {
163				legs.push({
164					action: label,
165					selector,
166					outcome: `FAIL: ${(error instanceof Error ? error.message : String(error)).split('\n')[0]}`,
167				});
168			}
169		};
170	
171		const waitFor = async (selector: string, label: string, ms = 10_000): Promise<boolean> => {
172			try {
173				await page.locator(selector).first().waitFor({ state: 'visible', timeout: ms });
174				legs.push({ waitFor: selector, label, outcome: 'visible' });
175				return true;
176			} catch {
177				legs.push({ waitFor: selector, label, outcome: 'ABSENT', url: new URL(page.url()).pathname });
178				return false;
179			}
180		};
181	
182		try {
183			await page.goto(`${appOrigin}/`, { waitUntil: 'domcontentloaded' });
184			await waitFor('[data-test=signin-username]', 'boot-signin');
185			await snapshot('initial');
186			// Signup — click the link; if it does not SPA-navigate, hard-load /signup.
187			await clickIfPresent('[data-test=signup]', 'click-signup');
188			if (!(await waitFor('[data-test=signup-first-name]', 'signup-after-link-click', 6_000))) {
189				await page.goto(`${appOrigin}/signup`, { waitUntil: 'domcontentloaded' });
190				await waitFor('[data-test=signup-first-name]', 'signup-after-hard-goto');
191			}
192			await typeIfPresent('[data-test=signup-first-name] input', actor.firstName, 'fill-first');
193			await typeIfPresent('[data-test=signup-last-name] input', actor.lastName, 'fill-last');
194			await typeIfPresent('[data-test=signup-username] input', actor.username, 'fill-username');
195			await typeIfPresent('[data-test=signup-password] input', actor.password, 'fill-password');
196			await typeIfPresent('[data-test=signup-confirmPassword] input', actor.password, 'fill-confirm');
197			await clickIfPresent('[data-test=signup-submit]', 'click-signup-submit');
198			await waitFor('[data-test=signin-username]', 'back-to-signin-after-signup');
199			await snapshot('after-signup');
200			// Signin
201			await typeIfPresent('[data-test=signin-username] input', actor.username, 'fill-signin-username');
202			await typeIfPresent('[data-test=signin-password] input', actor.password, 'fill-signin-password');
203			await clickIfPresent('[data-test=signin-submit]', 'click-signin-submit');
204			await delay(2_500);
205			await snapshot('after-signin');
206			// Onboarding
207			if (await waitFor('[data-test=user-onboarding-next]', 'onboarding-dialog', 8_000)) {
208				await clickIfPresent('[data-test=user-onboarding-next]', 'onboarding-next-1');
209				await typeIfPresent('[data-test=bankaccount-bankName-input] input', 'Versionless Bank', 'bank-name');
210				await typeIfPresent('[data-test=bankaccount-routingNumber-input] input', '987654321', 'routing');
211				await typeIfPresent('[data-test=bankaccount-accountNumber-input] input', '123456789', 'account');
212				await clickIfPresent('[data-test=bankaccount-submit]', 'bank-submit');
213				await delay(1_500);
214				await snapshot('after-bank');
215				await clickIfPresent('[data-test=user-onboarding-next]', 'onboarding-next-2');
216				await delay(1_000);
217			}
218			await snapshot('home');
219			const flushNet = (label: string): void => {
220				legs.push({ netSince: label, entries: network.slice(netCursor) });
221				netCursor = network.length;
222			};
223			flushNet('after-onboarding');
224			// Settings — fill first name and SUBMIT, measure the write endpoint.
225			await clickIfPresent('[data-test=sidenav-user-settings]', 'nav-settings');
226			await waitFor('[data-test=user-settings-firstName-input]', 'settings-form', 8_000);
227			await snapshot('settings');
228			await typeIfPresent('[data-test=user-settings-firstName-input]', 'VersionlessEdited', 'settings-first');
229			await typeIfPresent('[data-test=user-settings-lastName-input]', 'ProverEdited', 'settings-last');
230			await typeIfPresent('[data-test=user-settings-email-input]', 'prover@versionless.test', 'settings-email');
231			await typeIfPresent('[data-test=user-settings-phoneNumber-input]', '6155551234', 'settings-phone');
232			await clickIfPresent('[data-test=user-settings-submit]', 'settings-submit');
233			await delay(1_500);
234			flushNet('settings-submit');
235			// Money movement
236			await clickIfPresent('[data-test=nav-top-new-transaction]', 'new-transaction');
237			await waitFor('[data-test=user-list-search-input]', 'transaction-search', 8_000);
238			const searchDom = await page
239				.locator('[data-test=user-list-search-input]')
240				.first()
241				.evaluate((element) => element.outerHTML.slice(0, 400))
242				.catch(() => 'ABSENT');
243			legs.push({ debug: 'user-list-search-input outerHTML', html: searchDom });
244			await delay(1_500);
245			await waitFor('[data-test^=user-list-item-]', 'peer-results', 6_000);
246			await snapshot('peer-search');
247			flushNet('peer-search');
248			await clickIfPresent('[data-test^=user-list-item-]', 'pick-peer');
249			await waitFor('[data-test=transaction-create-amount-input]', 'amount-form', 8_000);
250			await snapshot('amount-form');
251			await typeIfPresent('[data-test=transaction-create-amount-input] input', '15', 'amount');
252			await typeIfPresent(
253				'[data-test=transaction-create-description-input] input',
254				'versionless-proof-payment',
255				'description',
256			);
257			await clickIfPresent('[data-test=transaction-create-submit-payment]', 'submit-payment');
258			await delay(2_500);
259			legs.push({ label: 'after-payment', url: new URL(page.url()).pathname });
260			flushNet('payment-submit');
261			await snapshot('after-payment');
262			// Feed / filter — home then each tab, measuring the feed endpoints.
263			await clickIfPresent('[data-test=sidenav-home]', 'nav-home');
264			await delay(1_200);
265			await clickIfPresent('[data-test=nav-public-tab]', 'public-tab');
266			await delay(1_200);
267			await clickIfPresent('[data-test=nav-contacts-tab]', 'contacts-tab');
268			await delay(1_200);
269			await clickIfPresent('[data-test=nav-personal-tab]', 'personal-tab');
270			await delay(1_200);
271			flushNet('feed-tabs');
272			await snapshot('feed');
273			// Notifications
274			await clickIfPresent('[data-test=sidenav-notifications]', 'nav-notifications');
275			await delay(1_500);
276			flushNet('notifications');
277			await snapshot('notifications');
278		} finally {
279			process.stdout.write(
280				`${canonicalize({ lane, staticOrigin: staticServer.origin, legs, consoleErrors, network })}\n`,
281			);
282			await context.close();
283			await browser.close();
284			await staticServer.close();
285			await backend.close();
286		}
287	}
288	
289	export async function main(args = process.argv.slice(2)): Promise<void> {
290		await probeCypressRwaLane(args[0] ?? 'baseline');
291	}
292	
293	if (basename(process.argv[1] ?? '') === 'react-cypress-rwa-probe.ts')
294		main().catch((error: unknown) => {
295			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
296			process.exitCode = 1;
297		});
298

